package com.example.url;
import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.Pattern;
import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.client.RestClient; import org.springframework.web.server.ResponseStatusException;
import java.net.URI; import java.time.Instant; import java.util.*;
@RestController @RequestMapping("/api/urls") public class UrlController {
 private final ShortUrlRepository repo; private final RestClient analytics; @Value("${app.base-url:http://localhost:8081}") String baseUrl;
 public UrlController(ShortUrlRepository repo,@Value("${analytics.url:http://localhost:8082}") String analyticsUrl){this.repo=repo;this.analytics=RestClient.builder().baseUrl(analyticsUrl).build();}
 public record CreateRequest(@NotBlank @Pattern(regexp="https?://.+",message="URL must start with http:// or https://") String url,Integer expiresInDays){}
 public record CreateResponse(String code,String shortUrl,String targetUrl,Instant createdAt,Instant expiresAt){}
 @PostMapping public ResponseEntity<CreateResponse> create(@Valid @RequestBody CreateRequest request){int days=request.expiresInDays()==null?0:request.expiresInDays();if(days<0||days>3650)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"expiresInDays must be between 0 and 3650");String code;do{code=UUID.randomUUID().toString().replace("-","").substring(0,7);}while(repo.findByCode(code).isPresent());Instant expiry=days==0?null:Instant.now().plusSeconds(days*86400L);ShortUrl saved=repo.save(new ShortUrl(request.url(),code,expiry));return ResponseEntity.status(HttpStatus.CREATED).body(new CreateResponse(code,baseUrl+"/"+code,saved.targetUrl,saved.createdAt,saved.expiresAt));}
 @GetMapping("/{code}") public Map<String,Object> get(@PathVariable String code){ShortUrl u=repo.findByCode(code).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Short URL not found"));return Map.of("code",u.code,"targetUrl",u.targetUrl,"createdAt",u.createdAt,"expiresAt",u.expiresAt==null?"never":u.expiresAt);}
 @GetMapping("/{code}/redirect") public ResponseEntity<Void> redirect(@PathVariable String code,@RequestHeader(value="Referer",required=false) String referer){ShortUrl u=repo.findByCode(code).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Short URL not found"));if(u.expiresAt!=null&&u.expiresAt.isBefore(Instant.now()))throw new ResponseStatusException(HttpStatus.GONE,"Short URL expired");try{analytics.post().uri("/api/analytics/clicks").body(Map.of("code",code,"referrer",referer==null?"direct":referer,"clickedAt",Instant.now().toString())).retrieve().toBodilessEntity();}catch(Exception ignored){}return ResponseEntity.status(HttpStatus.FOUND).location(URI.create(u.targetUrl)).build();}
 @DeleteMapping("/{code}") public ResponseEntity<Void> delete(@PathVariable String code){ShortUrl u=repo.findByCode(code).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Short URL not found"));repo.delete(u);return ResponseEntity.noContent().build();}
}
